<?php
require_once __DIR__.'/../config/fungsi.php';$data=[];$totals=[];foreach(['Kakang','Senduk'] as $cat){$q=$pdo->prepare('SELECT k.*,COUNT(v.id) total_suara FROM kontestan k LEFT JOIN voting v ON v.kontestan_id=k.id WHERE k.kategori=? GROUP BY k.id ORDER BY total_suara DESC,k.nomor_peserta');$q->execute([$cat]);$data[$cat]=$q->fetchAll();$totals[$cat]=array_sum(array_column($data[$cat],'total_suara'));}$updated=date('d-m-Y H:i:s');$page_title='Klasemen Voting';require __DIR__.'/../includes/header.php';?>
<div class="mb-4"><div class="eyebrow">Perolehan suara</div><h1 class="section-title">Klasemen Sementara</h1><p class="text-muted">Terakhir dibuka: <?= e($updated) ?></p></div>
<?php foreach($data as $cat=>$rows): ?><div class="panel mb-4"><div class="d-flex justify-content-between"><h2 class="h4 fw-bold"><?= $cat ?></h2><span class="badge text-bg-light">Total suara: <?= (int)$totals[$cat] ?></span></div><div class="table-responsive mt-3"><table class="table align-middle"><thead><tr><th>Ranking</th><th>Kontestan</th><th>Asal instansi</th><th>Suara</th><th>Persentase</th></tr></thead><tbody><?php foreach($rows as $i=>$k): $pct=$totals[$cat]>0?round($k['total_suara']/$totals[$cat]*100,1):0; ?><tr><td><strong>#<?= $i+1 ?></strong></td><td><div class="d-flex align-items-center gap-3"><img src="<?= e(base_url($k['foto']?:'assets/img/placeholder.svg')) ?>" width="48" height="48" class="rounded-circle" style="object-fit:cover"><div><strong><?= e($k['nama']) ?></strong><div class="small text-muted"><?= e($k['nomor_peserta']) ?></div></div></div></td><td><?= e($k['asal_instansi']) ?></td><td><strong><?= (int)$k['total_suara'] ?></strong></td><td><?= $pct ?>%</td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5" class="text-center text-muted">Belum ada data kontestan.</td></tr><?php endif; ?></tbody></table></div></div><?php endforeach; ?>
<?php require __DIR__.'/../includes/footer.php'; ?>